<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$pdo=db();$stats=['drums'=>(int)$pdo->query('SELECT COUNT(*) FROM drums')->fetchColumn(),'clients'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='client'")->fetchColumn(),'pending'=>(int)$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='Pending'")->fetchColumn(),'approved'=>(int)$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='Approved'")->fetchColumn()];$recent=$pdo->query('SELECT b.id,b.start_at,b.status,u.name client_name,d.name drum_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN drums d ON d.id=b.drum_id ORDER BY b.created_at DESC LIMIT 8')->fetchAll();page_header('Admin dashboard');?><section class="grid four"><?php foreach(['Drum kits'=>'drums','Clients'=>'clients','Pending requests'=>'pending','Approved bookings'=>'approved'] as $label=>$key):?><article class="stat"><span><?=e($label)?></span><strong><?=$stats[$key]?></strong></article><?php endforeach;?></section><div class="toolbar"><h2>Recent booking requests</h2><a class="button" href="bookings.php">Manage bookings</a></div><?php if(!$recent):?><div class="empty"><p>No booking requests yet.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Client</th><th>Drum</th><th>Session</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($recent as $b):?><tr><td><?=e($b['client_name'])?></td><td><?=e($b['drum_name'])?></td><td><?=e(date('M j, Y g:i A',strtotime($b['start_at'])))?></td><td><span class="<?=e(booking_status_class($b['status']))?>"><?=e($b['status'])?></span></td><td><a class="text-link" href="bookings.php">Review</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php page_footer();?>
